function can(admin,permission){if(!admin)return false;if(admin.permissions?.includes('*'))return true;if(admin.permissions?.includes(permission))return true;const [section,action]=String(permission).split('.');return action==='view'&&admin.permissions?.includes(`${section}.edit`)}
function hasView(admin,view){if(view==='team-terms')return !!admin;if(admin?.role==='founder')return true;const map={dashboard:null,students:'students',registrations:'students',batches:'batches',domains:'domains',tasks:'tasks',assessment:'assessment',payments:'payments',documents:'documents',communication:'communication',notifications:'communication',services:'services',support:'support',enquiries:'enquiries',settings:'settings',team:'team','team-terms':'team',audit:'audit'};const section=map[view];if(!section)return view==='dashboard';return admin?.permissions?.includes(`${section}.view`)||admin?.permissions?.includes(`${section}.edit`)}
