function filteredRegistrations(){const from=document.getElementById('regFrom').value,to=document.getElementById('regTo').value,dom=document.getElementById('regDomain').value,status=document.getElementById('regStatus').value;return students.filter(s=>{if(s.batch_start)return false;const day=(s.registration_date||'').slice(0,10);return(!from||day>=from)&&(!to||day<=to)&&(!dom||s.domain===dom)&&(!status||s.status===status)})}
