function renderRegistrations(){const list=filteredRegistrations();document.getElementById('regCount').textContent=`${list.length} students`;document.getElementById('registrationRows').innerHTML=list.map(s=>`<tr><td><input type="checkbox" class="reg-check" data-id="${s.id}" ${selectedIds.has(s.id)?'checked':''}></td><td><strong>${ae(s.student_id)}</strong><br>${ae(s.name)}</td><td>${ae(s.email)}<br>${ae(s.phone)}</td><td>${ae(s.country||'—')}</td><td>${ae(s.study_year||'—')}</td><td>${ae(s.domain)}</td><td>${ad(s.registration_date)}</td><td>${ad(s.batch_start)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No students match this filter.</td></tr>';document.querySelectorAll('.reg-check').forEach(c=>c.onchange=()=>{c.checked?selectedIds.add(c.dataset.id):selectedIds.delete(c.dataset.id);updateRegSelectButton()});updateRegSelectButton()}
function renderStudents(){const q=document.getElementById('studentSearch').value.trim().toLowerCase(),dom=document.getElementById('studentDomain').value;const list=students.filter(s=>(!q||[s.name,s.student_id,s.email,s.phone].join(' ').toLowerCase().includes(q))&&(!dom||s.domain===dom));document.getElementById('studentRows').innerHTML=list.map(s=>`<tr><td><strong>${ae(s.student_id)}</strong><br>${ae(s.name)}</td><td>${ae(s.email)}<br>${ae(s.phone)}</td><td>${ae(s.domain)}</td><td>${ad(s.registration_date)}</td><td>${ad(s.batch_start)}</td><td><span class="status ${statusClass(s.payment_status)}">${ae(s.payment_status)}</span></td><td>${ae(s.assessment_status)}</td><td>${ae(s.selection_status)}</td><td><button class="portal-btn secondary student-open" data-id="${s.id}">Open</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty">No students found.</td></tr>';document.querySelectorAll('.student-open').forEach(b=>b.onclick=()=>openStudent(b.dataset.id))}
