async function refreshNoteStatuses(){noteStatusByUser={};try{const [{data:notes,error:ne},{data:reads,error:re}]=await Promise.all([adminSB.from('sgt_student_notes').select('id,user_id,created_at').order('created_at',{ascending:false}).limit(500),adminSB.from('sgt_student_notification_reads').select('notification_id,user_id,read_at')]);if(ne||re)return;const readMap=new Map((reads||[]).map(r=>[`${r.user_id}:${r.notification_id}`,r.read_at]));for(const n of (notes||[])){if(noteStatusByUser[n.user_id])continue;const read_at=readMap.get(`${n.user_id}:${n.id}`)||null;noteStatusByUser[n.user_id]={seen:Boolean(read_at),created_at:n.created_at,read_at}}}catch(e){console.warn('Note status refresh failed',e)}}
async function sendStudentNote(){if(!can(admin,'communication.edit')&&!can(admin,'students.edit'))return toast('No permission.');const msg=(document.getElementById('notificationMessage')?.value||document.getElementById('studentNoteMessage')?.value||'').trim(),category=document.getElementById('notificationCategory')?.value||document.getElementById('studentNoteCategory')?.value;if(!msg)return toast('Enter a notification first.');if(!noteSelection.size)return toast('Select at least one student.');const rows=[...noteSelection].map(user_id=>({user_id,category,message:msg,created_by:admin.user.id}));const {error}=await adminSB.from('sgt_student_notes').insert(rows);if(error)return toast(error.message);await log('Sent student notification','student',rows.map(x=>x.user_id).join(','),{category,count:rows.length});const m=document.getElementById('notificationMessage')||document.getElementById('studentNoteMessage');if(m)m.value='';noteSelection.clear();await refreshNoteStatuses();if(document.getElementById('notificationStudentPanel')?.style.display!=='none')renderNotificationStudents();renderStudents();toast('Notification sent to selected students.')}

