function reassessmentQuestions(primary){return primary.map((q,i)=>{const prefix=['Compare or contrast the key idea in this question with a practical alternative: ','Suppose you had to explain this concept to a beginner. How would you approach it? ','What common mistake can occur with this concept, and how would you avoid it? ','Give a practical scenario where this concept would matter: ','How would you test or verify your understanding of this concept? ','If the first approach failed, what alternative would you consider? ','What trade-off should a developer consider when using this concept? ','How could this concept affect project quality or reliability? ','Describe a small real-world example involving this concept: ','What would you check first when solving a problem related to this concept? '][i];return prefix+q.replace(/^Explain |^What is |^Why is /,'').replace(/\.$/,'')+'?'});}
async function ensureDefaultAssessmentSets(){
  if(!admin||!can(admin,'assessment.edit')||!domains.length||!window.SGT_ASSESSMENT_BANK)return;
  const hasV2=questions.some(q=>q.question_set==='primary-v2');if(hasV2)return;
  try{await adminSB.from('sgt_assessment_questions').update({enabled:false}).in('question_set',['primary','reassessment']);}catch(e){console.warn('Old assessment question cleanup failed:',e.message)}
  const rows=[];
  for(const d of domains.filter(x=>x.enabled)){
    const bank=window.SGT_ASSESSMENT_BANK[d.name];if(!Array.isArray(bank)||bank.length<20)continue;
    bank.slice(0,20).forEach((item,i)=>rows.push({domain:d.name,question_set:'primary-v2',question_no:i+1,question:JSON.stringify({question:item.question,options:item.options}),enabled:true}));
    bank.slice(0,20).forEach((item,i)=>rows.push({domain:d.name,question_set:'reassessment-v2',question_no:i+1,question:JSON.stringify({question:`Second opportunity: ${item.question}`,options:item.options}),enabled:true}));
  }
  if(!rows.length)return;
  const {error}=await adminSB.from('sgt_assessment_questions').insert(rows);if(error){console.warn('Assessment v2 auto-publish failed:',error.message);return;}questions=[...questions,...rows];await log('Published 20-question domain assessment sets','assessment_question','',{version:'v2',count:rows.length});
}

async function seedDefaultAssessments(){if(!can(admin,'assessment.edit'))return toast('No permission.');await ensureDefaultAssessmentSets();const {error}=await adminSB.from('sgt_assessment_questions').update({enabled:true}).in('question_set',['primary-v2','reassessment-v2']);if(error)return toast(error.message);await log('Published default assessment questions','assessment_question','',{version:'v2'});await loadAll();toast('20-question domain assessment sets are published.')}
async function unpublishDefaultAssessments(){if(!can(admin,'assessment.edit'))return toast('No permission.');if(!confirm('Unpublish the default assessment questions? Students will not be able to start the assessment until the questions are published again.'))return;const {error}=await adminSB.from('sgt_assessment_questions').update({enabled:false}).in('question_set',['primary-v2','reassessment-v2']);if(error)return toast(error.message);await log('Unpublished default assessment questions','assessment_question','',{version:'v2'});await loadAll();toast('Assessment questions have been unpublished.')}
function assessmentQuestionsPublished(){return questions.some(q=>['primary-v2','reassessment-v2'].includes(q.question_set)&&q.enabled)}
function updateAssessmentPublishButton(){const b=document.getElementById('publishDefaultAssessments');if(!b)return;const published=assessmentQuestionsPublished();b.textContent=published?'Unpublish Questions':'Publish Default Questions';b.classList.toggle('danger',published);b.onclick=published?unpublishDefaultAssessments:seedDefaultAssessments}
function renderQuestions(){document.getElementById('questionRows').innerHTML=questions.filter(q=>q.enabled).map(q=>{let text=q.question;try{text=JSON.parse(q.question).question||text}catch(_){}return `<tr><td>${ae(q.domain)}</td><td>${ae(q.question_set)}</td><td>${ae(text)}</td><td>${q.question_no}</td><td><input type="checkbox" class="question-toggle" data-id="${q.id}" ${q.enabled?'checked':''}></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">No assessment questions published yet.</td></tr>';document.querySelectorAll('.question-toggle').forEach(c=>c.onchange=async()=>{if(!can(admin,'assessment.edit'))return toast('No permission.');const {error}=await adminSB.from('sgt_assessment_questions').update({enabled:c.checked}).eq('id',c.dataset.id);if(error)return toast(error.message);await log('Changed assessment question visibility','assessment_question',c.dataset.id,{enabled:c.checked});await loadAll()});updateAssessmentPublishButton()}

function assessmentResultRows(){
  const batch=document.getElementById('assessmentBatchFilter')?.value||assessmentCurrentBatch;
  const filter=document.getElementById('assessmentResultFilter')?.value||'';
  let rows=batch?(assessmentResultsByBatch.get(batch)||[]):[...assessmentResultsByBatch.values()].flat();
  return rows.filter(r=>!filter||(filter==='15plus'&&r.correct>=15)||(filter==='below15'&&r.correct<15)||(filter==='Submitted'&&r.assessmentStatus==='Complete')||(filter==='Under Review'&&r.reviewStatus==='Under Review')||(filter==='Selected'&&r.selectionStatus==='Selected')||(filter==='Not Selected'&&r.selectionStatus==='Not Selected'));
}
function renderAssessmentBatchList(){
  const el=document.getElementById('assessmentBatchList');if(!el)return;
  const entries=[...assessmentResultsByBatch.entries()].sort((a,b)=>b[0].localeCompare(a[0]));
  el.innerHTML=entries.map(([date,rows])=>`<button type="button" class="admin-list-item assessment-batch-item" data-batch="${ae(date)}" style="width:100%;text-align:left;background:#fff;border:1px solid var(--portal-border);cursor:pointer"><div><h3>${ae(ad(date))} Batch</h3><p>${rows.length} student${rows.length===1?'':'s'} submitted an assessment</p></div><span class="pill">Open Results →</span></button>`).join('')||'<div class="empty">No submitted assessment results yet.</div>';
  document.querySelectorAll('.assessment-batch-item').forEach(b=>b.onclick=()=>{document.getElementById('assessmentBatchFilter').value=b.dataset.batch;assessmentCurrentBatch=b.dataset.batch;renderAssessmentResults()});
}
function renderAssessmentResults(){
  const panel=document.getElementById('assessmentResultPanel');if(!panel)return;
  const batch=document.getElementById('assessmentBatchFilter')?.value||'';assessmentCurrentBatch=batch;
  const rows=assessmentResultRows();panel.style.display=rows.length||batch?'block':'none';
  const title=document.getElementById('assessmentResultTitle');if(title)title.textContent=batch?`${ad(batch)} Batch — Assessment Results`:'Assessment Results';
  const summary=document.getElementById('assessmentResultSummary');if(summary)summary.textContent=`${rows.length} result${rows.length===1?'':'s'} shown. Only assessment summary data is displayed.`;
  document.getElementById('assessmentResultRows').innerHTML=rows.map(r=>`<tr><td><input type="checkbox" class="assessment-result-check" data-id="${ae(r.userId)}" ${assessmentResultSelection.has(r.userId)?'checked':''}></td><td><strong>${ae(r.name)}</strong></td><td>${ae(r.studentId)}</td><td>20</td><td>${r.attempted}</td><td>${r.correct}</td><td><strong>${r.correct}/20</strong></td><td><span class="status ${statusClass(r.displayStatus)}">${ae(r.displayStatus||'Pending')}</span></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No assessment results match this filter.</td></tr>';
  document.querySelectorAll('.assessment-result-check').forEach(c=>c.onchange=()=>{c.checked?assessmentResultSelection.add(c.dataset.id):assessmentResultSelection.delete(c.dataset.id);updateAssessmentSelectionUI()});
  updateAssessmentSelectionUI();
}
function updateAssessmentSelectionUI(){const rows=assessmentResultRows(),all=rows.length>0&&rows.every(r=>assessmentResultSelection.has(r.userId));const btn=document.getElementById('assessmentSelectAll');if(btn)btn.textContent=all?'↩ Undo Selection':'Select All';const count=document.getElementById('assessmentResultSelectedCount');if(count)count.textContent=`${assessmentResultSelection.size} selected`;const undo=document.getElementById('assessmentUndoSelection');if(undo)undo.disabled=!assessmentResultSelection.size}
async function updateAssessmentSelectionStatus(status){if(!status)return;if(!can(admin,'assessment.edit'))return toast('No permission.');const ids=[...assessmentResultSelection];if(!ids.length)return toast('Select students first.');const selectedBefore=new Map(students.filter(s=>ids.includes(s.id)).map(s=>[s.id,s.selection_status]));const patch={review_status:status==='Under Review'?'Under Review':'Complete',updated_at:new Date().toISOString()};if(status==='Selected'||status==='Not Selected')patch.selection_status=status;if(status==='Selected')patch.offer_issue_date=new Date().toISOString().slice(0,10);const {error}=await adminSB.from('sgt_profiles').update(patch).in('id',ids);if(error)return toast(error.message);for(const id of ids){if(status==='Selected'&&selectedBefore.get(id)!=='Selected')await triggerSelectionEmail(id);if(status==='Selected'&&selectedBefore.get(id)!=='Selected'){const n=await adminSB.from('sgt_student_notes').insert({user_id:id,category:'Selection',message:'🎉 Selection Confirmed\nCongratulations! You have been selected for the SoftGrowTech Internship Program. Your selection has been successfully confirmed',created_by:admin.user.id});if(n.error)console.warn('Selection notification could not be created.',n.error.message)}}await log('Bulk updated assessment selection status','student',ids.join(','),{status,count:ids.length});assessmentResultSelection.clear();toast(`${ids.length} student${ids.length===1?'':'s'} updated to ${status}.`);await loadAll()}
async function loadAssessmentResults(){
  assessmentAttempts=[];assessmentAnswers=[];
  const [ar,ans]=await Promise.all([adminSB.from('sgt_assessment_attempts').select('*').eq('status','Complete').order('submitted_at',{ascending:false}),adminSB.from('sgt_assessment_answers').select('*')]);
  if(ar.error||ans.error){console.warn('Assessment result data unavailable:',ar.error?.message||ans.error?.message);assessmentResultsByBatch=new Map();renderAssessmentBatchList();renderAssessmentResults();return;}
  assessmentAttempts=ar.data||[];assessmentAnswers=ans.data||[];
  const answerByAttempt=new Map();for(const a of assessmentAnswers){if(!answerByAttempt.has(a.attempt_id))answerByAttempt.set(a.attempt_id,[]);answerByAttempt.get(a.attempt_id).push(a)}
  const qMap=new Map(questions.map(q=>[q.id,q]));const latest=new Map();
  for(const a of assessmentAttempts){const student=students.find(s=>s.student_id===a.student_id||s.id===a.user_id);if(!student||!student.batch_start)continue;const prior=latest.get(student.id);if(prior && new Date(a.submitted_at||0).getTime() <= new Date(prior.submitted_at||0).getTime())continue;const answers=answerByAttempt.get(a.id)||[];let attempted=0,correct=0;for(const ans of answers){const val=String(ans.answer||'').trim();if(val)attempted++;const q=qMap.get(ans.question_id);if(!q||!val)continue;try{const parsed=JSON.parse(q.question);if(Array.isArray(parsed.options)&&val===String(parsed.options[0]))correct++}catch(_){} }latest.set(student.id,{userId:student.id,name:student.name,studentId:student.student_id,batch:student.batch_start,attempted,correct,selectionStatus:student.selection_status||'Pending',assessmentStatus:student.assessment_status,reviewStatus:student.review_status,displayStatus:(student.selection_status&&student.selection_status!=='Pending')?student.selection_status:(student.review_status==='Under Review'?'Under Review':'Pending'),submitted_at:a.submitted_at});}
  const grouped=new Map();for(const r of latest.values()){if(!grouped.has(r.batch))grouped.set(r.batch,[]);grouped.get(r.batch).push(r)}for(const rows of grouped.values())rows.sort((a,b)=>b.correct-a.correct||a.name.localeCompare(b.name));assessmentResultsByBatch=grouped;
  const filter=document.getElementById('assessmentBatchFilter');if(filter){const current=filter.value;filter.innerHTML='<option value="">All batches</option>'+[...grouped.keys()].sort((a,b)=>b.localeCompare(a)).map(d=>`<option value="${ae(d)}">${ae(ad(d))} Batch</option>`).join('');if([...grouped.keys()].includes(current))filter.value=current;}
  renderAssessmentBatchList();renderAssessmentResults();
}
function paymentList(){const q=(document.getElementById('paymentSearch')?.value||'').trim().toLowerCase(),from=document.getElementById('payFrom')?.value||'',to=document.getElementById('payTo')?.value||'',batchFrom=document.getElementById('payBatchFrom')?.value||'',batchTo=document.getElementById('payBatchTo')?.value||'',dom=document.getElementById('payDomain')?.value||'',status=document.getElementById('payStatus')?.value||'',method=document.getElementById('payMethodFilter')?.value||'';const hasFilter=Boolean(q||from||to||batchFrom||batchTo||dom||status||method);if(!hasFilter)return[];return payments.filter(x=>{const st=students.find(s=>s.student_id===x.student_id);const hay=[x.student_id,st?.name,st?.email,st?.phone,x.transaction_id].join(' ').toLowerCase();const sd=(x.submitted_at||'').slice(0,10),bd=(st?.batch_start||'').slice(0,10);return(!q||hay.includes(q))&&(!from||sd>=from)&&(!to||sd<=to)&&(!batchFrom||bd>=batchFrom)&&(!batchTo||bd<=batchTo)&&(!dom||st?.domain===dom)&&(!status||x.status===status)&&(!method||x.method===method)})}
