async function paymentQrSignedUrl(ref){
  const value=String(ref||'');
  if(!value.startsWith('storage://payment-qr-codes/')) return value;
  const path=value.replace('storage://payment-qr-codes/','');
  const session=await adminSB.auth.getSession(),token=session.data.session?.access_token;
  if(!token)return '';
  const r=await fetch(`${SGT_URL}/functions/v1/sgt-payment-qr`,{method:'POST',headers:{Authorization:`Bearer ${token}`,apikey:SGT_KEY,'Content-Type':'application/json'},body:JSON.stringify({action:'signed-url',path})});
  const result=await r.json().catch(()=>({}));
  return r.ok?String(result.signed_url||''):'';
}
async function uploadPaymentQr(method,file){
  const session=await adminSB.auth.getSession(),token=session.data.session?.access_token;
  if(!token)throw Error('Admin session expired. Please sign in again.');
  const fd=new FormData();fd.append('action','upload');fd.append('method',method);fd.append('file',file,file.name);
  const r=await fetch(`${SGT_URL}/functions/v1/sgt-payment-qr`,{method:'POST',headers:{Authorization:`Bearer ${token}`,apikey:SGT_KEY},body:fd});
  const result=await r.json().catch(()=>({}));
  if(!r.ok)throw Error(result.error||'Unable to upload QR code to private storage.');
  return `storage://payment-qr-codes/${result.path}`;
}
async function removePaymentQr(ref){
  const value=String(ref||'');if(!value.startsWith('storage://payment-qr-codes/'))return;
  const session=await adminSB.auth.getSession(),token=session.data.session?.access_token;if(!token)throw Error('Admin session expired. Please sign in again.');
  const path=value.replace('storage://payment-qr-codes/','');
  const r=await fetch(`${SGT_URL}/functions/v1/sgt-payment-qr`,{method:'POST',headers:{Authorization:`Bearer ${token}`,apikey:SGT_KEY,'Content-Type':'application/json'},body:JSON.stringify({action:'remove',path})});
  const result=await r.json().catch(()=>({}));if(!r.ok)throw Error(result.error||'Unable to remove QR code.');
}
