async function renderTeam(){const box=document.getElementById('teamRows');if(!box)return;const q=(document.getElementById('teamSearch')?.value||'').trim().toLowerCase();const query=admin.role==='founder'?adminSB.from('sgt_admin_members').select('*').order('created_at',{ascending:false}):adminSB.from('sgt_admin_members').select('*').eq('user_id',admin.user.id).eq('active',true);const {data,error}=await query;if(error)return toast(error.message);const rows=(data||[]).filter(x=>!q||[x.email,x.role,(x.permissions||[]).join(' ')].join(' ').toLowerCase().includes(q));box.innerHTML=rows.map(x=>`<tr><td><strong>${ae(x.email)}</strong></td><td>${ae(x.role||'team_admin')}</td><td>${x.active?`<span class="status success">Active</span>`:`<button type="button" class="status danger team-permanent-remove" data-id="${ae(x.id)}" title="Permanently remove this team member">Removed</button>`}</td><td>${ad(x.created_at)}</td><td>${ae((x.permissions||[]).join(', ')||'No permissions')}</td><td>${admin.role==='founder'?`<button class="portal-btn secondary team-edit" data-id="${x.id}">Edit Permissions</button> <button class="portal-btn secondary team-password" data-id="${x.id}" data-email="${ae(x.email)}">Set Password</button> ${x.active?`<button class="portal-btn danger team-remove" data-id="${x.id}">Remove Access</button>`:`<button class="portal-btn primary team-restore" data-id="${x.id}">Restore</button> <button class="portal-btn danger team-permanent-remove" data-id="${x.id}">Remove Permanently</button>`}`:'<span class="pill">Your Access</span>'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No team members found.</td></tr>';document.querySelectorAll('.team-edit').forEach(b=>b.onclick=()=>editTeamMember(b.dataset.id));document.querySelectorAll('.team-password').forEach(b=>b.onclick=()=>setTeamPassword(b.dataset.id,b.dataset.email));document.querySelectorAll('.team-remove').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this team member access?'))return;const {error}=await adminSB.rpc('sgt_set_admin_member_active',{p_member_id:b.dataset.id,p_active:false});if(error)return toast(error.message);await log('Removed team admin access','admin_member',b.dataset.id);toast('Team member access removed. Click Removed to permanently delete this team member.');renderTeam()});document.querySelectorAll('.team-restore').forEach(b=>b.onclick=async()=>{if(admin.role!=='founder')return toast('Founder access only.');if(!confirm('Restore this team member access?'))return;const {error}=await adminSB.rpc('sgt_set_admin_member_active',{p_member_id:b.dataset.id,p_active:true});if(error)return toast(error.message);await log('Restored team admin access','admin_member',b.dataset.id);toast('Team member access restored.');renderTeam()});document.querySelectorAll('.team-permanent-remove').forEach(b=>b.onclick=async()=>{if(admin.role!=='founder')return toast('Founder access only.');if(!confirm('Permanently remove this team member? Their Management Console access will be revoked and their team-access record will be deleted. Activity Log records will be preserved.'))return;const session=await adminSB.auth.getSession(),token=session.data.session?.access_token;if(!token)return toast('Admin session expired. Please sign in again.');const r=await fetch(`${SGT_URL}/functions/v1/sgt-delete-team-member`,{method:'POST',headers:{Authorization:`Bearer ${token}`,apikey:SGT_KEY,'Content-Type':'application/json'},body:JSON.stringify({member_id:b.dataset.id})});const result=await r.json().catch(()=>({}));if(!r.ok)return toast(result.error||'Unable to permanently remove team member.');await log('Permanently removed team admin','admin_member',b.dataset.id,{activity_log_preserved:true});toast('Team member permanently removed.');renderTeam()})}
async function setTeamPassword(id,email){
  if(admin.role!=='founder')return toast('Founder access only.');
  const password=prompt(`Set a new password for ${email} (minimum 8 characters):`);
  if(password===null)return;
  if(password.length<8)return toast('Use a password with at least 8 characters.');
  const confirmPassword=prompt('Confirm the new password:');
  if(password!==confirmPassword)return toast('Passwords do not match.');
  const session=await adminSB.auth.getSession(),token=session.data.session?.access_token;
  if(!token)return toast('Admin session expired. Please sign in again.');
  const r=await fetch(`${SGT_URL}/functions/v1/sgt-set-team-password`,{method:'POST',headers:{Authorization:`Bearer ${token}`,apikey:SGT_KEY,'Content-Type':'application/json'},body:JSON.stringify({email,password})});
  const result=await r.json().catch(()=>({}));
  if(!r.ok)return toast(result.error||'Unable to update the team member password.');
  await log('Changed team admin password','admin_member',id,{email,password_managed_by:'Founder'});
  toast('Team member password updated.'); 
}
async function editTeamMember(id){
  if(admin.role!=='founder')return toast('Founder access only.');
  const {data,error}=await adminSB.from('sgt_admin_members').select('*').eq('id',id).maybeSingle();
  if(error)return toast(error.message);if(!data)return;
  const groups={
    Students:['view','add','edit','delete'],
    Batches:['view','add','edit','delete'],
    Domains:['view','add','edit','delete'],
    Tasks:['view','add','edit','delete'],
    Assessment:['view','add','edit','delete'],
    Payments:['view','verify','edit'],
    Documents:['view','edit'],
    Communication:['view','edit'],
    Services:['view','edit'],
    Support:['view','edit'],
    Enquiries:['view','edit'],
    Settings:['view','edit']
  };
  const body=document.getElementById('permissionModalBody');if(!body)return;
  body.innerHTML=Object.entries(groups).map(([label,actions])=>{const section=label.toLowerCase();return `<div class="permission-group"><strong>${label}</strong>${actions.map(action=>{const value=`${section}.${action}`;return `<label><input type="checkbox" class="permission-choice" value="${ae(value)}" ${(data.permissions||[]).includes(value)?'checked':''}> ${action.charAt(0).toUpperCase()+action.slice(1)}</label>`}).join('')}</div>`}).join('');
  const modal=document.getElementById('permissionModal');modal.hidden=false;modal.classList.add('open');
  const close=()=>{modal.hidden=true;modal.classList.remove('open')};
  document.getElementById('permissionCancel').onclick=close;document.getElementById('permissionCancelTop').onclick=close;
  document.getElementById('permissionSave').onclick=async()=>{
    const perms=[...body.querySelectorAll('.permission-choice:checked')].map(x=>x.value);
    const b=document.getElementById('permissionSave');b.disabled=true;b.textContent='Saving…';
    const {error:e}=await adminSB.rpc('sgt_update_admin_member_permissions',{p_member_id:id,p_permissions:perms});
    if(e){toast(e.message);b.disabled=false;b.textContent='Save Permissions';return}
    await log('Updated team admin permissions','admin_member',id,{email:data.email,permissions:perms});toast('Permissions updated.');b.disabled=false;b.textContent='Save Permissions';close();renderTeam();
  };
}
async function renderAudit(){if(admin.role!=='founder'){document.getElementById('auditRows').innerHTML='<tr><td colspan="4" class="empty">Founder access only.</td></tr>';return}const q=(document.getElementById('auditSearch')?.value||'').trim().toLowerCase();const {data,error}=await adminSB.from('sgt_admin_audit').select('*').order('created_at',{ascending:false}).limit(1000);if(error)return toast(error.message);const mr=await adminSB.from('sgt_admin_members').select('user_id,email,role');const members=mr.data||[];const names=new Map(members.map(m=>[m.user_id,m.email]));const teamBox=document.getElementById('auditTeamList');if(teamBox)teamBox.innerHTML='<span class="pill">Filter by team:</span>'+members.map(m=>`<button type="button" class="portal-btn secondary audit-team-chip" data-email="${ae(m.email)}">${ae(m.email)}</button>`).join('');teamBox?.querySelectorAll('.audit-team-chip').forEach(b=>b.onclick=()=>{const inp=document.getElementById('auditSearch');if(inp){inp.value=b.dataset.email;renderAudit()}});const rows=(data||[]).filter(x=>!q||[x.action,x.target_type,x.target_id,JSON.stringify(x.details||{}),names.get(x.admin_user)||'Founder'].join(' ').toLowerCase().includes(q));document.getElementById('auditRows').innerHTML=rows.map(x=>`<tr><td>${adt(x.created_at)}</td><td><strong>${ae(names.get(x.admin_user)||'Founder')}</strong><br>${ae(x.action)}</td><td>${ae(x.target_type||'')} ${ae(x.target_id||'')}</td><td><pre style="white-space:pre-wrap;margin:0;font:inherit;color:#475569">${ae(JSON.stringify(x.details||{},null,2))}</pre></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No activity matches your search.</td></tr>'}
async function loadAll(){try{const results=await Promise.all([adminSB.from('sgt_profiles').select('*').order('registration_date',{ascending:false}),adminSB.from('sgt_domains').select('*').order('name'),adminSB.from('sgt_batches').select('*').order('start_date',{ascending:false}),adminSB.from('sgt_tasks').select('*').order('title'),adminSB.from('sgt_assessment_questions').select('*').order('domain').order('question_set').order('question_no'),adminSB.from('sgt_payments').select('*').order('submitted_at',{ascending:false}),adminSB.from('sgt_client_enquiries').select('*').order('created_at',{ascending:false}),adminSB.from('sgt_support_queries').select('*').order('created_at',{ascending:false})]);for(const r of results)if(r.error)throw r.error;students=results[0].data||[];domains=results[1].data||[];batches=results[2].data||[];tasks=results[3].data||[];questions=results[4].data||[];payments=results[5].data||[];enquiries=results[6].data||[];support=results[7].data||[];await ensureDefaultAssessmentSets();renderDashboard();domainOptions('regDomain');domainOptions('studentDomain');domainOptions('payDomain');renderRegistrations();await refreshNoteStatuses();renderStudents();renderBatches();renderNotificationBatches();renderDomains();renderQuestions();renderDocuments();renderSupport();renderEnquiries();await renderTasks();await renderCommunication();await renderServices();await renderSettings();renderPayments();await loadAssessmentResults();if(currentView==='audit')await renderAudit();if(currentView==='team')await renderTeam()}catch(e){const er=document.querySelector('.admin-error');if(er)er.textContent=e.message;console.error(e)}}
async function setupAdmin2FA(){if(admin.role!=='founder')return toast('Founder access only.');const {data,error}=await adminSB.auth.mfa.enroll({factorType:'totp',friendlyName:'SoftGrowTech Founder Admin'});if(error)return toast(error.message);const modal=document.getElementById('twoFaSetup');modal.hidden=false;document.getElementById('twoFaQr').src=data.totp.qr_code;document.getElementById('twoFaSecret').textContent=data.totp.secret;document.getElementById('twoFaVerify').onclick=async()=>{const code=document.getElementById('twoFaCode').value.trim();const ch=await adminSB.auth.mfa.challenge({factorId:data.id});if(ch.error)return toast(ch.error.message);const vr=await adminSB.auth.mfa.verify({factorId:data.id,challengeId:ch.data.id,code});if(vr.error)return toast(vr.error.message);await saveSetting('admin_2fa',{enabled:true});await log('Enabled founder 2FA','security','admin_2fa');modal.hidden=true;toast('Two-factor authentication enabled.');renderSettings()}}
function notificationBatchList(){const q=(document.getElementById('notificationBatchSearch')?.value||'').trim().toLowerCase();return batches.slice().sort((a,b)=>new Date(b.start_date)-new Date(a.start_date)).filter(b=>!q||dateFmt(b.start_date).toLowerCase().includes(q)||String(b.start_date).includes(q));}
function renderNotificationBatches(){const list=notificationBatchList();const el=document.getElementById('notificationBatchRows');if(!el)return;el.innerHTML=list.map(b=>{const count=students.filter(s=>s.batch_start===b.start_date).length;return `<button type="button" class="admin-list-item notification-batch-item" data-batch-id="${ae(b.id)}"><div><h3>SoftGrowTech ${ae(dateFmt(b.start_date))} Batch</h3><p>${count} students • Click to send notifications</p></div><span class="pill">Open →</span></button>`}).join('')||'<div class="empty">No batches found.</div>';el.querySelectorAll('.notification-batch-item').forEach(b=>b.onclick=()=>openNotificationBatch(b.dataset.batchId));}
function openNotificationBatch(batchId){const b=batches.find(x=>x.id===batchId);if(!b)return;noteSelection.clear();const panel=document.getElementById('notificationStudentPanel');if(!panel)return;panel.dataset.batchId=batchId;panel.style.display='block';document.getElementById('notificationBatchTitle').textContent=`SoftGrowTech ${dateFmt(b.start_date)} Batch`;document.getElementById('notificationStudentSearch').value='';renderNotificationStudents();panel.scrollIntoView({behavior:'smooth',block:'start'});}
function renderNotificationStudents(){const panel=document.getElementById('notificationStudentPanel');if(!panel)return;const b=batches.find(x=>x.id===panel.dataset.batchId);if(!b)return;const q=(document.getElementById('notificationStudentSearch')?.value||'').trim().toLowerCase();const list=students.filter(s=>s.batch_start===b.start_date&&(!q||[s.name,s.phone,s.student_id,s.email].join(' ').toLowerCase().includes(q)));const all=list.length>0&&list.every(s=>noteSelection.has(s.id));const count=students.filter(s=>s.batch_start===b.start_date).length;document.getElementById('notificationBatchCount').textContent=`${count} students in batch`;document.getElementById('notificationSelectedCount').textContent=`${noteSelection.size} selected`;const btn=document.getElementById('notificationSelectAll');btn.textContent=all?'Undo Selection':'Select All';document.getElementById('notificationStudentRows').innerHTML=list.map(s=>{const ns=noteStatusByUser[s.id];const cell=ns?`<span class="status ${ns.seen?'success':'blue'}">${ns.seen?'Seen':'Sent'}</span><br><small>${ad(ns.created_at)}${ns.seen&&ns.read_at?' • Seen '+adt(ns.read_at):''}</small>`:'<span style="color:#94a3b8">—</span>';return `<tr><td><input type="checkbox" class="notification-student-check" data-id="${ae(s.id)}" ${noteSelection.has(s.id)?'checked':''}></td><td><strong>${ae(s.student_id)}</strong><br>${ae(s.name)}</td><td>${ae(s.phone)}</td><td>${ae(s.email)}</td><td>${cell}</td><td><button type="button" class="portal-btn secondary notification-student-open" data-id="${ae(s.id)}">History</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No students found in this batch.</td></tr>';document.querySelectorAll('.notification-student-check').forEach(c=>c.onchange=()=>{c.checked?noteSelection.add(c.dataset.id):noteSelection.delete(c.dataset.id);renderNotificationStudents()});document.querySelectorAll('.notification-student-open').forEach(b=>b.onclick=()=>openStudent(b.dataset.id));}
function initNotifications(){document.getElementById('notificationBatchSearch')?.addEventListener('input',renderNotificationBatches);document.getElementById('notificationStudentSearch')?.addEventListener('input',renderNotificationStudents);document.getElementById('notificationSelectAll')?.addEventListener('click',()=>{const panel=document.getElementById('notificationStudentPanel');const b=panel&&batches.find(x=>x.id===panel.dataset.batchId);if(!b)return;const q=(document.getElementById('notificationStudentSearch')?.value||'').trim().toLowerCase();const list=students.filter(s=>s.batch_start===b.start_date&&(!q||[s.name,s.phone,s.student_id,s.email].join(' ').toLowerCase().includes(q)));const all=list.length>0&&list.every(s=>noteSelection.has(s.id));list.forEach(s=>all?noteSelection.delete(s.id):noteSelection.add(s.id));renderNotificationStudents()});document.getElementById('notificationUndoSelection')?.addEventListener('click',()=>{noteSelection.clear();renderNotificationStudents()});document.getElementById('sendNotification')?.addEventListener('click',sendStudentNote);}

